on conflict (sku) do update set
  mpn = excluded.mpn,
  slug = excluded.slug,
  title = excluded.title,
  short_description = excluded.short_description,
  description = excluded.description,
  brand_id = excluded.brand_id,
  category_id = excluded.category_id,
  manufacturer_name = excluded.manufacturer_name,
  status = 'published',
  visibility = 'public',
  featured = excluded.featured,
  currency = excluded.currency,
  price = excluded.price,
  price_visibility = 'public',
  price_is_estimate = true,
  stock_quantity = excluded.stock_quantity,
  stock_status = excluded.stock_status,
  minimum_order_quantity = excluded.minimum_order_quantity,
  lead_time_min_days = excluded.lead_time_min_days,
  lead_time_max_days = excluded.lead_time_max_days,
  condition = excluded.condition,
  packaging = excluded.packaging,
  country_of_origin = excluded.country_of_origin,
  datasheet_url = excluded.datasheet_url,
  specifications = excluded.specifications,
  published_at = excluded.published_at,
  updated_at = excluded.updated_at,
  archived_at = null,
  deleted_at = null,
  embedding_status = 'pending',
  embedding_error = null;

create or replace view public.public_catalog_products as
select
  p.id,
  p.sku,
  p.mpn,
  p.slug,
  p.title,
  p.short_description,
  p.description,
  b.name as brand_name,
  b.slug as brand_slug,
  c.name as category_name,
  c.slug as category_slug,
  p.manufacturer_name,
  p.status,
  p.visibility,
  p.featured,
  p.currency,
  case when p.price_visibility = 'public' then p.price else null end as price,
  case when p.price_visibility = 'public' then p.price else null end as public_price_sort,
  p.price_visibility,
  p.stock_quantity,
  p.stock_status,
  p.minimum_order_quantity,
  p.lead_time_min_days,
  p.lead_time_max_days,
  p.condition,
  p.packaging,
  p.country_of_origin,
  p.datasheet_url,
  p.specifications,
  p.sku_normalized,
  p.mpn_normalized,
  img.public_url as primary_image_url,
  img.alt_text as primary_image_alt,
  p.published_at,
  p.updated_at,
  p.price_is_estimate
from public.products p
left join public.brands b on b.id = p.brand_id
left join public.categories c on c.id = p.category_id
left join lateral (
  select public_url, alt_text
  from public.product_images
  where product_id = p.id
  order by is_primary desc, sort_order asc, created_at asc
  limit 1
) img on true
where p.status = 'published'
  and p.visibility = 'public'
  and p.archived_at is null
  and p.deleted_at is null;

commit;
